  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B026",
      "proposed_laureates": ["Francis Halzen"],
      "assessment": {
        "nobel_worthiness": "Opening neutrino astronomy with high-energy astrophysical neutrinos is a major discovery that gives access to sources inaccessible to electromagnetic telescopes.",
        "attribution": "Halzen was a leading architect and advocate of IceCube, but the detector and discovery depended on a large international collaboration; sole credit needs careful scrutiny.",
        "maturity": "The astrophysical neutrino signal is established through multiple analyses and growing event samples, though source identification remains incomplete.",
        "uncertainties": ["Whether the decisive contribution can fairly be attributed to one individual rather than the collaboration."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B003",
      "proposed_laureates": ["Michel Della Negra", "Peter Jenni", "Tejinder S. Virdee"],
      "assessment": {
        "nobel_worthiness": "The discovery of the Higgs boson completed a central prediction of particle physics and confirmed the mechanism underlying the origin of elementary-particle masses.",
        "attribution": "These three are recognized leaders of the ATLAS and CMS experiments; their roles in building and leading the experiments are substantial, while the discovery itself was a collective achievement.",
        "maturity": "The discovery has been repeatedly confirmed, and subsequent measurements have strengthened the Higgs boson's place in the Standard Model.",
        "uncertainties": ["How to recognize decisive leadership while representing two collaborations involving thousands of contributors."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B002",
      "proposed_laureates": ["Charles L. Bennett", "David N. Spergel", "Lyman A. Page Jr."],
      "assessment": {
        "nobel_worthiness": "WMAP's precise full-sky mapping of the cosmic microwave background established a quantitative foundation for modern precision cosmology.",
        "attribution": "Bennett and Page led the experimental mission and its measurements; Spergel made a major contribution to interpreting the data and extracting cosmological parameters.",
        "maturity": "The results have been confirmed and refined by later observations, including Planck, and remain foundational.",
        "uncertainties": ["The boundary between mission leadership, instrument contributions, and theoretical interpretation deserves close review."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B019",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision timekeeping and enabled tests of fundamental physics with unprecedented sensitivity.",
        "attribution": "Katori and Ye independently developed leading approaches that made optical clocks practical and exceptionally precise.",
        "maturity": "The technique has been demonstrated repeatedly, with steadily improving performance and concrete applications in precision measurement.",
        "uncertainties": ["Whether the prize should recognize the clock concept and its realization together, or a narrower technical contribution."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B007",
      "proposed_laureates": ["Alexei Kitaev", "Andrew M. Steane", "Peter W. Shor"],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can be protected against noise in principle, making scalable quantum computation physically conceivable.",
        "attribution": "Shor and Steane independently introduced landmark codes, while Kitaev developed foundational topological approaches; these are distinct, complementary contributions.",
        "maturity": "The theory is firmly established and experimental demonstrations have advanced substantially, though large-scale fault-tolerant quantum computing remains unfinished.",
        "uncertainties": ["How much experimental realization should be expected before recognizing this theoretical foundation."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B005",
      "proposed_laureates": ["Maura McLaughlin", "Michael Kramer", "Richard N. Manchester"],
      "assessment": {
        "nobel_worthiness": "Pulsar timing evidence for a nanohertz gravitational-wave background opens a new observational window on massive black-hole binaries and the low-frequency universe.",
        "attribution": "These researchers made central contributions to long-term pulsar timing and international collaboration efforts, but the result is inherently collective across pulsar timing arrays.",
        "maturity": "Several collaborations report consistent evidence, but the signal's origin and detailed properties are not yet settled.",
        "uncertainties": ["The background's astrophysical interpretation and the distinction between strong evidence and a fully characterized detection."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B004",
      "proposed_laureates": ["Eli Yablonovitch", "John D. Joannopoulos", "Sajeev John"],
      "assessment": {
        "nobel_worthiness": "Photonic crystals introduced a powerful way to control light through periodic structure, with broad consequences for optics and photonic devices.",
        "attribution": "Yablonovitch and John independently established key ideas, while Joannopoulos helped develop the theory and its applications.",
        "maturity": "The field is mature, with extensive experimental confirmation and continuing use in photonics.",
        "uncertainties": ["Whether the impact of the original concept merits recognition apart from the many later developments in photonic engineering."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B006",
      "proposed_laureates": ["Immanuel Bloch", "Markus Greiner", "Peter Zoller"],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices created a controllable platform for studying quantum many-body physics and simulating models that are difficult to solve otherwise.",
        "attribution": "Bloch and Greiner made landmark experimental demonstrations, and Zoller helped establish the theoretical vision; Cirac's contribution is also important and should be considered.",
        "maturity": "The platform has produced a rich body of results, but its reach as a predictive simulator for difficult physical systems is still developing.",
        "uncertainties": ["How to distinguish foundational demonstrations from later advances across a broad and active field."]
      }
    }
  ]
}
